class Car {
    String color;
    int speed;

    void accelerate() {
        speed += 10;
    }
}

public class Main {
    public static void main(String[] args) {
        Car car1 = new Car();
        car1.color = "Red";
        car1.accelerate();

        Car car2 = new Car();
        car2.color = "Blue";

        System.out.println("Car 1 Speed: " + car1.speed); // 10
        System.out.println("Car 2 Speed: " + car2.speed); // 0
    }
}
